def roman_to_int(s: str) -> int:
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    if not s:
        raise ValueError("Input string cannot be empty")

    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    valid_chars = set(values)

    for ch in s:
        if ch not in valid_chars:
            raise ValueError(f"Invalid character: {ch}")

    # Check for invalid repetition
    for i in range(len(s)):
        ch = s[i]
        if ch in 'VLD':
            if i + 1 < len(s) and s[i + 1] == ch:
                raise ValueError(f"Invalid repetition: {ch}{ch}")
        elif ch in 'IXCM':
            count = 1
            j = i + 1
            while j < len(s) and s[j] == ch:
                count += 1
                j += 1
            if count > 3:
                raise ValueError(f"Invalid repetition: {ch * count}")
            i = j - 1

    # Check for valid subtractive combinations
    valid_subtractive = {'IV', 'IX', 'XL', 'XC', 'CD', 'CM'}
    for i in range(len(s) - 1):
        pair = s[i] + s[i + 1]
        if values[s[i]] < values[s[i + 1]]:
            if pair not in valid_subtractive:
                raise ValueError(f"Invalid subtractive combination: {pair}")

    # Convert to integer
    result = 0
    for i in range(len(s)):
        if i + 1 < len(s) and values[s[i]] < values[s[i + 1]]:
            result -= values[s[i]]
        else:
            result += values[s[i]]

    # Verify the result is within valid range
    if result < 1 or result > 3999:
        raise ValueError(f"Result {result} is out of valid range")

    # Additional validation: check that the numeral follows proper Roman numeral rules
    # We'll do a more thorough check by trying to reconstruct the numeral from the integer
    # and comparing it to the input

    def int_to_roman(num):
        val = [
            1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1
        ]
        syms = [
            'M', 'CM', 'D', 'CD', 'C', 'XC', 'L', 'XL', 'X', 'IX', 'V', 'IV', 'I'
        ]
        roman_num = ''
        for i in range(len(val)):
            while num >= val[i]:
                roman_num += syms[i]
                num -= val[i]
        return roman_num

    if int_to_roman(result) != s:
        raise ValueError(f"Invalid Roman numeral: {s}")

    return result
